/**
 * Plain text still arriving, with a steady caret (`design/components/streaming-text.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/streaming-text.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { claimSlot, resolveSlot, scope, type Defaults } from '@polymorph/solid'
import styles from '@polymorph/recipes/ai/streaming-text.module.css'
import Skeleton from '../structure/Skeleton'

export type StreamingTextSize = NonNullable<StreamingTextProps['size']>

export interface StreamingTextProps {
  /**
   * The text received so far, verbatim, with whitespace and line breaks kept as content.
   */
  children: JSX.Element
  /**
   * The text step (Text's `sm` or `md`), for the same reason Text has two.
   */
  size?: 'sm' | 'md'
  /**
   * Whether more is coming, which shows the caret and sets `aria-busy` on the root.
   */
  streaming?: boolean
}

/** Plain text still arriving, with a steady caret. */
export default function StreamingText(given: StreamingTextProps): JSX.Element {
  const props = mergeProps(
    { streaming: false, size: 'md' } as Defaults<StreamingTextProps, 'streaming' | 'size'>,
    claimSlot(given),
  )
  return scope(() => {
    const childrenSlot = resolveSlot(() => props.children)
    return (
      <div
        class={styles.root}
        data-size={props.size}
        data-state={props.streaming ? 'streaming' : undefined}
        data-pending={props.streaming && childrenSlot.text() === '' ? '' : undefined}
        aria-busy={props.streaming ? true : undefined}
        data-member="streaming-text"
      >
        {props.streaming && childrenSlot.text() === '' ? (
          <Skeleton shape="text" textStep={props.size} width={9} />
        ) : (
          <p class={styles.text}>
            {childrenSlot()}
            {props.streaming ? <span class={styles.caret} aria-hidden="true" /> : null}
          </p>
        )}
      </div>
    )
  })
}
